                      <motion.span
                        initial={{ scale: 0 }}
                        animate={{ scale: 1 }}
                        transition={{ ...springTransition, delay: 0.3 + index * 0.05 }}
                        className={clsx(
                          'text-lg',
                          result?.isCorrect ? 'text-signal' : 'text-terracotta'
