            </motion.div>
          )}

          {phase === 'debrief' && (
            <MissionDebrief
              key="debrief"
              mission={mission}
              score={score}
              onNext={handleNextMission}
              onReturn={handleReturnToPlanet}
            />
          )}
        </AnimatePresence>
      </div>
    </div>
  )
}

